import { useEffect, useMemo, useRef, useState, type Ref } from "react";
import { Camera, CheckCircle2, CircleOff, ClipboardList, FileText, Images, MapPinCheck, Plus, Printer, ScanBarcode, ShieldCheck, Truck, UserCheck, X } from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { COMPACT_FORM_FIELD } from "@/components/ui/compact-form";
import { QRScanner, type ParsedQRCode } from "@/components/qr";
import { CustomerCustodyApi, CustomerCustodyApiError, customerCustodyErrorText, type CustomerCustodyCatalogItem, type CustomerStorageLot, type CustomerStoredItem } from "./api";
import CustodyDescriptionSearch from "./CustodyDescriptionSearch";
import CustodyStageQuery from "./CustodyStageQuery";
import { damageNoteToken, damagePhotoToken, FALLBACK_CUSTODY_CATALOG, catalogRows, observationToken, parseDamageNote, parseDamagePhoto, parseObservation } from "./catalog";

type WorkflowStep = "handoff" | "unloading" | "description" | "putaway";
type ScannerTarget = "unloading" | "description" | "location" | "putaway";
type Props = Readonly<{ lot: CustomerStorageLot; api: CustomerCustodyApi; canOperate: boolean; onSaved(lot: CustomerStorageLot): void; onMove(item: CustomerStoredItem): void; onLabelsGenerated?(items: readonly CustomerStoredItem[], declaredContentQuantity: number | null): void }>;
type ActionInput = Readonly<{ action: string; item?: CustomerStoredItem | null; scanCode?: string | null; locationRef?: string | null; unitType?: string | null; packageFormCode?: string | null; genericContents?: readonly string[] | null; inspectionResult?: string | null; locationStatus?: string | null; excessReason?: string | null; labelQuantity?: number | null; declaredContentQuantity?: number | null; notes?: string | null; evidence?: readonly string[] | null }>;

const PRIMARY = "inline-flex min-h-9 items-center justify-center gap-1.5 rounded border border-[#003366] bg-[#003366] px-3 text-xs font-semibold text-white hover:bg-[#00264d] disabled:opacity-40";
const SECONDARY = "inline-flex min-h-9 items-center justify-center gap-1.5 rounded border border-slate-300 bg-white px-3 text-xs font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-40";
const STEPS = Object.freeze([{ id: "handoff", label: "Preparar" }, { id: "unloading", label: "Descargar" }, { id: "description", label: "Describir" }, { id: "putaway", label: "Ubicar" }] as const);
const LOCATION_STATUS: Record<string, string> = { AVAILABLE: "Disponible", IN_USE: "En uso", FULL: "Llena", BLOCKED: "Bloqueada", RESERVED_EXIT: "Reservada para salida", REVIEW_REQUIRED: "Revisión visual" };

function stepFor(lot: CustomerStorageLot): WorkflowStep { if (["PLANNED", "IN_TRANSIT", "ARRIVED"].includes(lot.receptionStage)) return "handoff"; if ((lot.receptionStage === "RECEIVING" && lot.items.length === 0) || lot.items.some((item) => item.status === "EXPECTED")) return "unloading"; if (lot.items.some((item) => item.status === "IN_CUSTODY" && !["CLEARED", "PREVERIFIED"].includes(item.inspectionStatus))) return "description"; return "putaway"; }
function formatDateTime(value: string | null) { return value ? new Intl.DateTimeFormat("es-DO", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)) : "Pendiente"; }
function inventoryNumber(item: CustomerStoredItem) { return String(item.inventoryNumber).padStart(4, "0"); }
function itemLabel(item: CustomerStoredItem) { return `ART. ${inventoryNumber(item)}`; }
function hasRecordedCondition(item: CustomerStoredItem) { return item.identitySource !== "GENERATED_AT_RECEPTION" || item.evidence?.some((entry) => entry.startsWith("COND|") || entry.startsWith("OBS|")) === true; }
function isScanAddressedAction(action: string) { return action === "SCAN_ITEM" || action === "PUT_AWAY_SCAN" || action === "STAGE_EXCESS"; }
async function compressedPhoto(file: File) {
  const source = await new Promise<HTMLImageElement>((resolve, reject) => { const image = new Image(); image.onload = () => resolve(image); image.onerror = reject; image.src = URL.createObjectURL(file); });
  const ratio = Math.min(1, 1280 / Math.max(source.naturalWidth, source.naturalHeight));
  const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(source.naturalWidth * ratio)); canvas.height = Math.max(1, Math.round(source.naturalHeight * ratio));
  canvas.getContext("2d")?.drawImage(source, 0, 0, canvas.width, canvas.height); URL.revokeObjectURL(source.src);
  return canvas.toDataURL("image/jpeg", 0.68);
}

export default function CustodyReceptionWorkflow({ lot, api, canOperate, onSaved, onLabelsGenerated }: Props) {
  const [step, setStep] = useState<WorkflowStep>(() => stepFor(lot));
  const [scannerTarget, setScannerTarget] = useState<ScannerTarget | null>(null);
  const [externalScanner, setExternalScanner] = useState(true);
  const [dockCode, setDockCode] = useState(""); const [activeItemRef, setActiveItemRef] = useState<string | null>(null); const [damageLocation, setDamageLocation] = useState<string | null>(null); const [damageCondition, setDamageCondition] = useState<string | null>(null);
  const [damagePhotos, setDamagePhotos] = useState<readonly string[]>([]); const [damageNote, setDamageNote] = useState(""); const [damageReportOpen, setDamageReportOpen] = useState(false);
  const [labelOpen, setLabelOpen] = useState(false); const [catalogOpen, setCatalogOpen] = useState(false); const [discardOpen, setDiscardOpen] = useState(false); const [packageFormCode, setPackageFormCode] = useState("BOX"); const [labelQuantity, setLabelQuantity] = useState(1); const [declaredContentQuantity, setDeclaredContentQuantity] = useState("");
  const [descriptionCode, setDescriptionCode] = useState(""); const [descriptionItemRef, setDescriptionItemRef] = useState<string | null>(null); const [contents, setContents] = useState<readonly string[]>([]); const [note, setNote] = useState("");
  const [locationCode, setLocationCode] = useState(""); const [putAwayCode, setPutAwayCode] = useState("");
  const [excessReason, setExcessReason] = useState("CONTRACTED_CAPACITY_FULL");
  const [putAwayTarget, setPutAwayTarget] = useState<"location" | "putaway">("location"); const [lastLocatedItemRef, setLastLocatedItemRef] = useState<string | null>(null);
  const [catalog, setCatalog] = useState<readonly CustomerCustodyCatalogItem[]>(FALLBACK_CUSTODY_CATALOG);
  const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null); const scanRef = useRef<HTMLInputElement>(null); const locationInputRef = useRef<HTMLInputElement>(null); const putAwayInputRef = useRef<HTMLInputElement>(null); const externalScanBufferRef = useRef(""); const externalScanCommitTimerRef = useRef<number | null>(null); const actionInFlightRef = useRef(false); const latestLotRef = useRef(lot); const scanQueueRef = useRef<Promise<void>>(Promise.resolve()); const selectedItemRef = useRef<string | null>(null); const selectedDamageLocationRef = useRef<string | null>(null); const selectedDamageConditionRef = useRef<string | null>(null);

  latestLotRef.current = lot;
  useEffect(() => { const controller = new AbortController(); api.catalogItems(undefined, controller.signal).then((rows) => { if (rows.length) setCatalog(rows); }).catch(() => undefined); return () => controller.abort(); }, [api]);

  useEffect(() => { setStep((current) => current === "handoff" || lot.receptionStage === "CLOSED" ? stepFor(lot) : current); }, [lot]);
  const expected = useMemo(() => lot.items.filter((item) => item.status === "EXPECTED"), [lot.items]);
  const received = useMemo(() => lot.items.filter((item) => item.status !== "EXPECTED"), [lot.items]);
  const toDescribe = useMemo(() => received.filter((item) => item.status !== "HOLD" && !["CLEARED", "PREVERIFIED"].includes(item.inspectionStatus)), [received]);
  const holds = useMemo(() => lot.items.filter((item) => item.status === "HOLD" || item.inspectionStatus === "HOLD"), [lot.items]);
  const finalLocated = useMemo(() => received.filter((item) => item.location && item.location.locationRef !== lot.receptionLocation.locationRef), [received, lot.receptionLocation.locationRef]);
  const canClose = lot.items.length > 0 && expected.length === 0 && toDescribe.length === 0 && holds.length === 0 && finalLocated.length === lot.items.length;
  const activeItem = lot.items.find((item) => item.itemRef === activeItemRef) || null;
  const descriptionItem = lot.items.find((item) => item.itemRef === descriptionItemRef) || null;
  const descriptionNeedsCondition = descriptionItem ? !hasRecordedCondition(descriptionItem) : false;
  const selectedLocationItems = locationCode ? lot.items.filter((item) => item.location?.locationRef === locationCode) : [];
  const isExcessLocation = Boolean(locationCode && locationCode === lot.warehouse.excessExitLocation?.locationRef);
  const selectedLocation = selectedLocationItems[0]?.location ?? (locationCode === lot.receptionLocation.locationRef ? lot.receptionLocation : isExcessLocation && lot.warehouse.excessExitLocation ? { ...lot.warehouse.excessExitLocation, occupancyStatus: "RESERVED_EXIT", occupancyVersion: 0 } : null);
  const damageLocations = useMemo(() => catalogRows(catalog, "DAMAGE_LOCATION"), [catalog]);
  const conditions = useMemo(() => catalogRows(catalog, "CONDITION"), [catalog]);
  const packageForms = useMemo(() => catalogRows(catalog, "PACKAGE_FORM"), [catalog]);
  const itemNames = useMemo(() => catalogRows(catalog, "ITEM_NAME"), [catalog]);
  const damagedItems = useMemo(() => lot.items.filter((item) => item.condition === "DAMAGED"), [lot.items]);

  const focusScanner = () => window.setTimeout(() => scanRef.current?.focus(), 0);
  const feedback = (message: string) => { setNotice(message); navigator.vibrate?.(35); };
  const fetchCurrentLot = async () => { const current = (await api.list("", "ALL")).find((row) => row.storageRef === latestLotRef.current.storageRef) ?? null; if (current) latestLotRef.current = current; return current; };
  const act = async (input: ActionInput, startingLot = latestLotRef.current): Promise<CustomerStorageLot | null> => {
    if (actionInFlightRef.current) { setError("Espere la confirmación de la lectura anterior."); return null; }
    actionInFlightRef.current = true;
    setSaving(true); setError(null); setNotice(null);
    try {
      let actionLot = startingLot;
      const execute = (currentLot: CustomerStorageLot) => {
        const currentItem = input.item ? currentLot.items.find((row) => row.itemRef === input.item?.itemRef) ?? input.item : null;
        return api.receptionAction({ storageRef: currentLot.storageRef, action: input.action, itemRef: isScanAddressedAction(input.action) ? null : currentItem?.itemRef ?? null, scanCode: input.scanCode ?? null, locationRef: input.locationRef ?? null, unitType: input.unitType ?? null, packageFormCode: input.packageFormCode ?? null, genericContents: input.genericContents ?? null, inspectionResult: input.inspectionResult ?? null, locationStatus: input.locationStatus ?? null, excessReason: input.excessReason ?? null, labelQuantity: input.labelQuantity ?? null, occurredAt: new Date().toISOString(), notes: input.notes ?? null, evidence: input.evidence ?? null, expectedLotVersion: currentLot.version, expectedItemVersion: currentItem?.version ?? null });
      };
      let saved: CustomerStorageLot;
      try { saved = await execute(actionLot); }
      catch (cause) {
        if (!(cause instanceof CustomerCustodyApiError) || cause.code !== "CUSTOMER_CUSTODY_VERSION_CONFLICT") throw cause;
        const currentLot = await fetchCurrentLot();
        if (!currentLot) throw cause;
        actionLot = currentLot; latestLotRef.current = currentLot; onSaved(currentLot);
        saved = await execute(currentLot);
      }
      latestLotRef.current = saved; onSaved(saved);
      if (input.action === "PREPARE_LABEL") { const known = new Set(actionLot.items.map((item) => item.itemRef)); const generated = saved.items.filter((item) => !known.has(item.itemRef)).sort((left, right) => left.itemCode.localeCompare(right.itemCode)); if (generated.length) onLabelsGenerated?.(generated, input.declaredContentQuantity ?? null); setLabelOpen(false); setLabelQuantity(1); setDeclaredContentQuantity(""); feedback(`${generated.length} ${generated.length === 1 ? "etiqueta preparada" : "etiquetas preparadas"}. Cada QR debe escanearse al descargar.`); }
      if (input.action === "DISCARD_UNUSED_LABELS") { setDiscardOpen(false); feedback("Las etiquetas no usadas quedaron anuladas y ya no cuentan como bultos pendientes."); setStep(stepFor(saved)); }
      if (input.action === "FINISH_UNLOADING") { setDiscardOpen(false); feedback("Descarga finalizada. El tiempo y las lecturas quedaron registrados."); setStep(stepFor(saved)); }
      if (input.action === "CONFIRM_HANDOFF") { feedback("Entrega confirmada. Inicie la descarga."); setStep("unloading"); }
      if (input.action === "RECORD_VEHICLE_PHOTO") feedback("Foto de llegada guardada en la recepción.");
      if (input.action === "SCAN_ITEM") feedback("Unidad recibida. Puede escanear la siguiente etiqueta o registrar su condición.");
      if (input.action === "RECORD_CONDITION") feedback("Observación de condición registrada.");
      if (input.action === "DESCRIBE_ITEM") { feedback("Contenido guardado."); if (!saved.items.some((row) => row.status === "IN_CUSTODY" && !["CLEARED", "PREVERIFIED"].includes(row.inspectionStatus))) setStep("putaway"); }
      if (input.action === "PUT_AWAY_SCAN") feedback("Unidad ubicada.");
      if (input.action === "STAGE_EXCESS") feedback("Excedente retenido. Comercial ya puede autorizar su devolución.");
      focusScanner(); return saved;
    } catch (cause) { setError(customerCustodyErrorText(cause)); navigator.vibrate?.([80, 40, 80]); return null; } finally { actionInFlightRef.current = false; setSaving(false); }
  };
  const selectInspectionItem = (itemRef: string | null) => { selectedItemRef.current = itemRef; setActiveItemRef(itemRef); };
  const clearObservationSelection = () => { selectedDamageLocationRef.current = null; selectedDamageConditionRef.current = null; setDamageLocation(null); setDamageCondition(null); setDamagePhotos([]); setDamageNote(""); };
  const receiveItem = async (code: string) => { let sourceLot = latestLotRef.current; let item = sourceLot.items.find((row) => [row.itemCode, row.externalCode].includes(code)); if (!item) { const currentLot = await fetchCurrentLot(); if (currentLot) { sourceLot = currentLot; onSaved(currentLot); item = currentLot.items.find((row) => [row.itemCode, row.externalCode].includes(code)); } } if (!item) { setError("Código no reconocido. Prepare una etiqueta si la unidad llegó sin identificación."); return; } clearObservationSelection(); if (item.status !== "EXPECTED") { selectInspectionItem(item.itemRef); if (!hasRecordedCondition(item)) feedback(`${itemLabel(item)} ya estaba recibido y aún necesita inspección.`); else feedback(`${itemLabel(item)} ya estaba recibido. Puede agregar otra observación.`); return; } const saved = await act({ action: "SCAN_ITEM", item, scanCode: code }, sourceLot); if (saved) selectInspectionItem(item.itemRef); };
  const recordObservation = async (locationCode: string, conditionCode: string, photos: readonly string[] = [], noteText = "") => { const currentLot = latestLotRef.current; const item = currentLot.items.find((row) => row.itemRef === selectedItemRef.current); if (!item) { setError("Primero escanee o seleccione la etiqueta de la unidad."); return; } const location = damageLocations.find((row) => row.code === locationCode); const condition = conditions.find((row) => row.code === conditionCode); if (!location || !condition) { setError("La localización o condición ya no está activa en el catálogo."); return; } if (condition.code !== "NO_VISIBLE_DAMAGE" && photos.length === 0) { setError("Tome por lo menos una fotografía para evidenciar la condición observada."); return; } const observationRef = crypto.randomUUID(); const evidence = [observationToken(location, condition, observationRef), ...photos.map((photo) => damagePhotoToken(observationRef, photo)), ...(noteText.trim() ? [damageNoteToken(observationRef, noteText.trim())] : [])]; const humanNote = `${location.label}: ${condition.label}${noteText.trim() ? ` · ${noteText.trim()}` : ""}`; const saved = await act({ action: "RECORD_CONDITION", item, evidence, notes: condition.code === "NO_VISIBLE_DAMAGE" ? null : `EVIDENCE:${observationRef}|${humanNote}` }, currentLot); if (saved) { clearObservationSelection(); setDockCode(""); if (condition.code === "NO_VISIBLE_DAMAGE") selectInspectionItem(null); } };
  const chooseDamageLocation = async (code: string) => { if (!selectedItemRef.current) { setError("Primero escanee o seleccione la etiqueta del artículo."); return; } selectedDamageLocationRef.current = code; setDamageLocation(code); setError(null); const condition = selectedDamageConditionRef.current; if (condition) feedback("Daño identificado. Tome la fotografía de evidencia."); else feedback("Localización seleccionada. Puede elegir ahora la condición."); };
  const chooseCondition = async (code: string) => { if (!selectedItemRef.current) { setError("Primero escanee o seleccione la etiqueta del artículo."); return; } selectedDamageConditionRef.current = code; setDamageCondition(code); setError(null); if (code === "NO_VISIBLE_DAMAGE") await recordObservation("GENERAL", code); else { const location = selectedDamageLocationRef.current; if (location) feedback("Daño identificado. Tome la fotografía de evidencia."); else feedback("Condición seleccionada. Puede elegir ahora la localización."); } };
  const addDamagePhotos = async (files: FileList | null) => { if (!files?.length) return; try { const remaining = Math.max(0, 4 - damagePhotos.length); const prepared = await Promise.all(Array.from(files).slice(0, remaining).map(compressedPhoto)); if (prepared.some((photo) => photo.length > 400_000)) { setError("Una fotografía es demasiado grande. Intente nuevamente con menor resolución."); return; } setDamagePhotos((current) => [...current, ...prepared].slice(0, 4)); setError(null); } catch { setError("No se pudo preparar la fotografía del artículo."); } };
  const handleDockCode = async (raw: string) => { const code = raw.trim(); if (!code) return; if (code.startsWith("DLOC:")) { await chooseDamageLocation(code.slice(5)); setDockCode(""); focusScanner(); return; } if (code.startsWith("COND:")) { await chooseCondition(code.slice(5)); setDockCode(""); focusScanner(); return; } await receiveItem(code); setDockCode(""); };
  const loadDescriptionItem = (item: CustomerStoredItem) => { setDescriptionItemRef(item.itemRef); selectInspectionItem(hasRecordedCondition(item) ? null : item.itemRef); clearObservationSelection(); setPackageFormCode(item.identitySource === "GENERATED_AT_RECEPTION" && item.genericContents.length === 0 ? "" : item.packageFormCode ?? packageForms.find((row) => row.baseValue === item.unitType)?.code ?? "OTHER"); setContents(item.genericContents); setNote(item.notes || ""); setDescriptionCode(""); };
  const handleDescriptionCode = (raw: string) => { const code = raw.trim(); const item = received.find((row) => [row.itemCode, row.externalCode].includes(code)); if (!item) { setError("Unidad no encontrada entre los artículos recibidos."); return; } loadDescriptionItem(item); };
  const saveDescription = async () => { if (!descriptionItem) return; const saved = await act({ action: "DESCRIBE_ITEM", item: descriptionItem, packageFormCode, genericContents: contents, notes: note.trim() || null }); if (saved) { setDescriptionItemRef(null); selectInspectionItem(null); setContents([]); setNote(""); setPackageFormCode(""); setDescriptionCode(""); focusScanner(); } };
  const putAway = async (value = putAwayCode, destination = locationCode) => { const code = value.trim(); const currentLot = latestLotRef.current; const item = currentLot.items.find((row) => [row.itemCode, row.externalCode].includes(code)); if (!destination || !item) { setError("Escanee primero una ubicación válida y luego una unidad recibida."); return; } const excess = destination === currentLot.warehouse.excessExitLocation?.locationRef; const saved = await act({ action: excess ? "STAGE_EXCESS" : "PUT_AWAY_SCAN", item, scanCode: code, locationRef: destination, excessReason: excess ? excessReason : null, notes: excess ? "Excedente retenido durante la recepción; pendiente de autorización comercial" : null }, currentLot); if (saved) { setLastLocatedItemRef(item.itemRef); setPutAwayCode(""); setPutAwayTarget("putaway"); window.setTimeout(() => putAwayInputRef.current?.focus(), 0); } };
  const queueCode = (target: ScannerTarget, code: string) => { scanQueueRef.current = scanQueueRef.current.then(async () => { if (target === "unloading") await handleDockCode(code); if (target === "description") handleDescriptionCode(code); if (target === "location") { setLocationCode(code); setPutAwayTarget("putaway"); feedback("Ubicación activa. Escanee ahora los artículos que colocará en ella."); window.setTimeout(() => putAwayInputRef.current?.focus(), 0); } if (target === "putaway") await putAway(code); }).catch((cause) => setError(customerCustodyErrorText(cause))); };
  const scanned = (result: ParsedQRCode) => { const value = result.rawValue.trim(); if (scannerTarget) queueCode(scannerTarget, value); setScannerTarget(null); };
  const selectFromStageQuery = (stage: "unloading" | "description" | "putaway", item: CustomerStoredItem) => {
    setError(null);
    if (stage === "description") { loadDescriptionItem(item); focusScanner(); return; }
    if (stage === "unloading" && item.status !== "EXPECTED") { selectInspectionItem(item.itemRef); clearObservationSelection(); feedback(`${itemLabel(item)} seleccionado. Puede agregar una o varias observaciones.`); return; }
    if (stage === "unloading") { feedback(`${itemLabel(item)} está ${item.status === "EXPECTED" ? "pendiente de escanear" : "recibido"}.`); focusScanner(); return; }
    feedback(`${itemLabel(item)} seleccionado. Escanee su etiqueta para confirmar la ubicación.`); focusScanner();
  };
  const changeStep = (next: WorkflowStep) => { setStep(next); setError(null); setNotice(null); setDescriptionItemRef(null); selectInspectionItem(null); clearObservationSelection(); if (next !== "putaway") { setLocationCode(""); setPutAwayCode(""); setPutAwayTarget("location"); } };
  const saveVehiclePhoto = async (file: File | null) => { if (!file) return; try { const photo = await compressedPhoto(file); if (photo.length > 400_000) { setError("La foto es demasiado grande. Intente nuevamente con menor resolución."); return; } await act({ action: "RECORD_VEHICLE_PHOTO", evidence: [photo], notes: "Foto del vehículo al llegar" }); } catch { setError("No se pudo preparar la foto del vehículo."); } };

  useEffect(() => {
    if (!externalScanner) return;
    const timeout = window.setTimeout(() => scanRef.current?.focus(), 0);
    return () => window.clearTimeout(timeout);
  }, [externalScanner, step]);

  useEffect(() => {
    if (!externalScanner) { externalScanBufferRef.current = ""; if (externalScanCommitTimerRef.current !== null) window.clearTimeout(externalScanCommitTimerRef.current); externalScanCommitTimerRef.current = null; return; }
    const commitExternalScan = () => {
      if (externalScanCommitTimerRef.current !== null) window.clearTimeout(externalScanCommitTimerRef.current);
      externalScanCommitTimerRef.current = null;
      const code = externalScanBufferRef.current.trim();
      externalScanBufferRef.current = "";
      if (!code) return;
      if (step === "unloading") queueCode("unloading", code);
      if (step === "description") queueCode("description", code);
      if (step === "putaway") queueCode(putAwayTarget, code);
    };
    const captureExternalScan = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      const scannerField = target?.getAttribute("data-custody-scanner") === "true";
      if (target?.matches("input, textarea, select, [contenteditable='true']") && !scannerField) return;
      if (event.key === "Enter" || event.key === "Tab") {
        if (!externalScanBufferRef.current.trim()) return;
        event.preventDefault(); event.stopPropagation(); commitExternalScan();
        return;
      }
      if (event.key === "Backspace") { event.preventDefault(); event.stopPropagation(); externalScanBufferRef.current = externalScanBufferRef.current.slice(0, -1); return; }
      if (event.key.length !== 1 || event.ctrlKey || event.metaKey || event.altKey) return;
      event.preventDefault(); event.stopPropagation(); externalScanBufferRef.current += event.key;
      if (externalScanCommitTimerRef.current !== null) window.clearTimeout(externalScanCommitTimerRef.current);
      externalScanCommitTimerRef.current = window.setTimeout(commitExternalScan, 120);
    };
    window.addEventListener("keydown", captureExternalScan, true);
    return () => { window.removeEventListener("keydown", captureExternalScan, true); if (externalScanCommitTimerRef.current !== null) window.clearTimeout(externalScanCommitTimerRef.current); externalScanCommitTimerRef.current = null; };
  });

  const preparedLabels = expected.filter((item) => item.identitySource === "GENERATED_AT_RECEPTION");

  return <section className="overflow-hidden rounded-2xl border bg-white shadow-sm" aria-label="Recepción y cadena de custodia">
    <div className="flex flex-wrap items-center justify-between gap-2 bg-[#003366] px-3 py-3 text-white">
      <div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-sky-200">Recepción activa</p><h4 className="text-sm font-bold">{lot.client.name}</h4><p className="text-[10px] text-sky-100">{lot.manifestCode || lot.lotCode} · {lot.warehouse.name}</p></div>
      <button type="button" aria-pressed={externalScanner} onClick={() => { setExternalScanner((value) => !value); focusScanner(); }} className={`inline-flex min-h-9 items-center gap-1.5 rounded-lg border px-3 text-[11px] font-bold transition-colors ${externalScanner ? "border-orange-300 bg-orange-500 text-white shadow-sm hover:bg-orange-600" : "border-sky-300/50 text-white hover:bg-white/10"}`}><ScanBarcode className="h-4 w-4" />{externalScanner ? "Scanner activo" : "Activar scanner"}</button>
    </div>
    <nav className="grid grid-cols-4 border-b bg-slate-50 p-1" aria-label="Etapas de recepción">
      {STEPS.map((row, index) => { const active = step === row.id; return <button key={row.id} type="button" aria-pressed={active} onClick={() => changeStep(row.id)} className={`flex min-h-12 items-center justify-center gap-1.5 rounded-lg px-1 text-[10px] font-bold sm:text-xs ${active ? "bg-[#003366] text-white" : "text-slate-500 hover:bg-slate-100"}`}><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-full border text-[9px] ${active ? "border-white/50" : "border-slate-300"}`}>{index + 1}</span>{row.label}</button>; })}
    </nav>
    <div className="grid grid-cols-4 divide-x border-b bg-white"><Metric label="Sin escanear" value={expected.length} /><Metric label="Recibidas" value={received.length} /><Metric label="Por describir" value={toDescribe.length} alert={toDescribe.length > 0} /><Metric label="Ubicadas" value={finalLocated.length} /></div>
    <div className="min-w-0 p-3 sm:p-4">
      {step === "handoff" && <div><Handoff lot={lot} canOperate={canOperate} saving={saving} labelCount={preparedLabels.length} onPrepareLabels={() => setLabelOpen(true)} onPrintPrepared={() => onLabelsGenerated?.(preparedLabels, null)} onDiscardLabels={() => setDiscardOpen(true)} onVehiclePhoto={(file) => void saveVehiclePhoto(file)} onAction={(action) => void act({ action })} />{(labelOpen || preparedLabels.length === 0) && <PrepareLabel labelQuantity={labelQuantity} declaredContentQuantity={declaredContentQuantity} saving={saving} onLabelQuantity={setLabelQuantity} onDeclaredContentQuantity={setDeclaredContentQuantity} onCancel={() => setLabelOpen(false)} onSave={() => void act({ action: "PREPARE_LABEL", labelQuantity, declaredContentQuantity: declaredContentQuantity ? Number(declaredContentQuantity) : null })} />}</div>}
      {step === "unloading" && <div><Header icon={ScanBarcode} title="Descargar" hint="Escanee cada etiqueta. La inspección puede registrarse en cualquier orden y con varias observaciones." badge={`${received.length} recibidas`} /><div className="mt-4 flex gap-2"><ScannerInput inputRef={scanRef} value={dockCode} onChange={setDockCode} onEnter={(value) => queueCode("unloading", value)} external={externalScanner} placeholder={activeItem ? "Escanee otra etiqueta o una condición/localización" : "Escanee la etiqueta del artículo"} /><button type="button" className={`${PRIMARY} min-w-11 px-0`} onClick={() => setScannerTarget("unloading")} aria-label="Escanear con la cámara"><ScanBarcode className="h-5 w-5" /></button></div><div className="mt-2 flex flex-wrap items-center justify-between gap-2"><p className="text-[11px] text-slate-500">{expected.length} etiquetas disponibles · {received.length} artículos descargados</p><div className="flex flex-wrap gap-1">{damagedItems.length > 0 && <button type="button" className={SECONDARY} onClick={() => setDamageReportOpen(true)}><Images className="h-4 w-4" />Evidencias ({damagedItems.length})</button>}<button type="button" className={SECONDARY} onClick={() => setCatalogOpen(true)}><Printer className="h-4 w-4" />Catálogo QR</button><button type="button" className={SECONDARY} onClick={() => changeStep("handoff")}><Plus className="h-4 w-4" />Etiquetas</button>{received.length > 0 && !lot.unloadingFinishedAt && <button type="button" className={SECONDARY} disabled={!canOperate || saving} onClick={() => setDiscardOpen(true)}><CircleOff className="h-4 w-4" />Finalizar descarga</button>}</div></div>{activeItem ? <ConditionPanel item={activeItem} locations={damageLocations} conditions={conditions} location={damageLocation} condition={damageCondition} photos={damagePhotos} note={damageNote} saving={saving} onLocation={(code) => void chooseDamageLocation(code)} onCondition={(code) => void chooseCondition(code)} onPhotos={(files) => void addDamagePhotos(files)} onRemovePhoto={(index) => setDamagePhotos((current) => current.filter((_, currentIndex) => currentIndex !== index))} onNote={setDamageNote} onSave={() => damageLocation && damageCondition && void recordObservation(damageLocation, damageCondition, damagePhotos, damageNote)} onFinish={() => { selectInspectionItem(null); clearObservationSelection(); feedback("Inspección terminada. Escanee el siguiente artículo."); }} /> : <SimpleState text="Listo para escanear el siguiente artículo." />}<CustodyStageQuery stage="unloading" lot={lot} onSelect={(item) => selectFromStageQuery("unloading", item)} /></div>}
      {step === "description" && <div><Header icon={FileText} title="Describir" hint="Escanee el artículo y registre su tipo físico y contenido." badge={`${toDescribe.length} pendientes`} alert={toDescribe.length > 0} /><div className="mt-4 flex gap-2"><ScannerInput inputRef={scanRef} value={descriptionCode} onChange={setDescriptionCode} onEnter={(value) => queueCode("description", value)} external={externalScanner} placeholder="Escanee el artículo que va a describir" /><button type="button" className={`${PRIMARY} min-w-11 px-0`} onClick={() => setScannerTarget("description")} aria-label="Escanear con la cámara"><ScanBarcode className="h-5 w-5" /></button></div>{descriptionItem ? descriptionNeedsCondition ? <div className="mt-3"><p className="rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[11px] font-semibold text-amber-900">{itemLabel(descriptionItem)} necesita completar su condición antes de describirse.</p><ConditionPanel item={descriptionItem} locations={damageLocations} conditions={conditions} location={damageLocation} condition={damageCondition} photos={damagePhotos} note={damageNote} saving={saving} onLocation={(code) => void chooseDamageLocation(code)} onCondition={(code) => void chooseCondition(code)} onPhotos={(files) => void addDamagePhotos(files)} onRemovePhoto={(index) => setDamagePhotos((current) => current.filter((_, currentIndex) => currentIndex !== index))} onNote={setDamageNote} onSave={() => damageLocation && damageCondition && void recordObservation(damageLocation, damageCondition, damagePhotos, damageNote)} onFinish={() => { selectInspectionItem(null); clearObservationSelection(); }} /></div> : <DescriptionForm key={descriptionItem.itemRef} item={descriptionItem} packageFormCode={packageFormCode} contents={contents} note={note} packageForms={packageForms} itemNames={itemNames} saving={saving} onPackageFormCode={setPackageFormCode} onContents={setContents} onNote={setNote} onCancel={() => { setDescriptionItemRef(null); selectInspectionItem(null); focusScanner(); }} onSave={() => void saveDescription()} /> : <SimpleState text={toDescribe.length ? `${toDescribe.length} artículos pendientes. Escanee el siguiente.` : "Todos los artículos recibidos están descritos."} />}<CustodyStageQuery stage="description" lot={lot} onSelect={(item) => selectFromStageQuery("description", item)} /></div>}
      {step === "putaway" && <div>
        <div className="flex items-start justify-between gap-2"><Header icon={MapPinCheck} title="Ubicar" hint="Escanee primero la ubicación y después cada artículo que deposita allí." badge={selectedLocation ? LOCATION_STATUS[selectedLocation.occupancyStatus] || selectedLocation.occupancyStatus : "Sin ubicación"} /><button type="button" className={`${SECONDARY} h-9 w-9 shrink-0 px-0`} onClick={() => setScannerTarget(putAwayTarget)} aria-label={`Escanear ${putAwayTarget === "location" ? "ubicación" : "artículo"} con la cámara`} title="Escanear con la cámara"><ScanBarcode className="h-4 w-4" /></button></div>
        <div className="mt-4 grid gap-3 sm:grid-cols-2"><ScanField inputRef={locationInputRef} label="1. Ubicación" value={locationCode} placeholder="Escanear ubicación" external={externalScanner} active={putAwayTarget === "location"} onFocus={() => setPutAwayTarget("location")} onChange={(value) => { setLocationCode(value); setPutAwayTarget("location"); }} onEnter={() => queueCode("location", locationCode)} /><ScanField inputRef={putAwayInputRef} label="2. Artículo" value={putAwayCode} placeholder="Escanear artículo" external={externalScanner} active={putAwayTarget === "putaway"} disabled={!locationCode} onFocus={() => setPutAwayTarget("putaway")} onChange={(value) => { setPutAwayCode(value); setPutAwayTarget("putaway"); }} onEnter={() => putAway()} /></div>
        {locationCode && <div className={`mt-3 rounded-lg border px-3 py-2 ${isExcessLocation ? "border-amber-300 bg-amber-50" : "border-emerald-300 bg-emerald-50"}`}><p className={`text-[10px] font-bold uppercase tracking-wide ${isExcessLocation ? "text-amber-800" : "text-emerald-700"}`}>{isExcessLocation ? "Salida temporal de excedentes" : "Ubicación activa"}</p><p className={`font-mono text-sm font-black ${isExcessLocation ? "text-amber-950" : "text-emerald-950"}`}>{selectedLocation?.path || locationCode}</p><p className={`text-[10px] ${isExcessLocation ? "text-amber-800" : "text-emerald-800"}`}>{isExcessLocation ? `Los bultos quedarán bajo custodia. Gracia: ${lot.warehouse.excessGraceHours} h; luego ${lot.warehouse.excessCurrency} ${lot.warehouse.excessDailyRate.toFixed(2)} diarios por bulto.` : "Permanece activa hasta que marque llena o cambie de ubicación."}</p></div>}
        {isExcessLocation && <label className="mt-3 block text-xs font-semibold text-slate-700">Motivo del excedente<select value={excessReason} onChange={(event) => setExcessReason(event.target.value)} className={`${COMPACT_FORM_FIELD} mt-1 w-full`}><option value="CONTRACTED_CAPACITY_FULL">Se llenó la capacidad contratada</option><option value="UNDECLARED_ADDITIONAL_ITEMS">Artículos adicionales no declarados</option><option value="CUSTOMER_DECLINED_EXPANSION">Cliente rechazó ampliar el espacio</option><option value="COMPANY_ESTIMATION_ERROR">Diferencia en la estimación de la empresa</option><option value="WAREHOUSE_CAPACITY_FAILURE">Indisponibilidad del almacén</option><option value="OTHER_AUTHORIZED">Otro motivo autorizado</option></select></label>}
        <div className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-50 px-3 py-2"><p className="text-[11px] text-slate-600"><b>{selectedLocationItems.length}</b> artículos registrados en esta ubicación.</p><div className="flex flex-wrap gap-1"><button type="button" className={SECONDARY} disabled={!locationCode} onClick={() => { setLocationCode(""); setPutAwayCode(""); setPutAwayTarget("location"); window.setTimeout(() => locationInputRef.current?.focus(), 0); }}>Cambiar ubicación</button>{!isExcessLocation && <button type="button" className={SECONDARY} disabled={!canOperate || saving || !selectedLocation} onClick={() => void act({ action: "SET_LOCATION_STATUS", locationRef: locationCode, locationStatus: "FULL", notes: "Ubicación marcada llena por inspección visual" }).then((saved) => { if (saved) { setLocationCode(""); setPutAwayTarget("location"); } })}>Marcar llena</button>}{lastLocatedItemRef && <button type="button" className={SECONDARY} onClick={() => { const item = lot.items.find((row) => row.itemRef === lastLocatedItemRef); setPutAwayCode(item?.itemCode || ""); setLocationCode(""); setPutAwayTarget("location"); feedback("Escanee la nueva ubicación; luego confirme el mismo artículo para conservar la trazabilidad."); }}>Reubicar último</button>}</div></div>
        {!lot.warehouse.excessExitLocation && <p className="mt-3 rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[11px] text-amber-900">Administración todavía no ha configurado la salida temporal de excedentes para este almacén.</p>}
        <CustodyStageQuery stage="putaway" lot={lot} onSelect={(item) => selectFromStageQuery("putaway", item)} /><CloseReception lot={lot} expected={expected.length} toDescribe={toDescribe.length} holds={holds.length} finalLocated={finalLocated.length} canClose={canClose} canOperate={canOperate} saving={saving} onClose={() => void act({ action: "CLOSE" })} />
      </div>}
      {notice && <p role="status" className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-800">{notice}</p>}{error && <p role="alert" className="mt-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-800">{error}</p>}
    </div>
    {scannerTarget && <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/70 p-3"><div className="relative w-full max-w-md"><button type="button" aria-label="Cerrar cámara" onClick={() => setScannerTarget(null)} className="absolute right-2 top-2 z-10 grid h-9 w-9 place-items-center rounded-full bg-white shadow"><X className="h-4 w-4" /></button><QRScanner title={scannerTarget === "location" ? "Escanear ubicación" : "Escanear código"} onScan={scanned} onClose={() => setScannerTarget(null)} /></div></div>}{catalogOpen && <ConditionCatalog locations={damageLocations} conditions={conditions} onClose={() => setCatalogOpen(false)} />}{damageReportOpen && <DamageEvidenceReport lot={lot} onClose={() => setDamageReportOpen(false)} />}{discardOpen && <DiscardUnusedLabelsDialog count={preparedLabels.length} saving={saving} onCancel={() => setDiscardOpen(false)} onConfirm={() => void act({ action: "FINISH_UNLOADING", notes: preparedLabels.length ? `Descarga finalizada; se anularon ${preparedLabels.length} etiquetas no utilizadas.` : "Descarga finalizada sin etiquetas sobrantes." })} />}
  </section>;
}

function ScannerInput({ inputRef, value, onChange, onEnter, external, placeholder }: { inputRef?: Ref<HTMLInputElement>; value: string; onChange(value: string): void; onEnter(value: string): void; external: boolean; placeholder: string }) { return <label className="relative min-w-[210px] flex-1"><span className="sr-only">Código escaneado</span><ScanBarcode className={`pointer-events-none absolute left-3 top-2.5 h-4 w-4 ${external ? "text-orange-700" : "text-sky-700"}`} /><input ref={inputRef} data-custody-scanner="true" value={value} inputMode="text" enterKeyHint="done" onChange={(event) => onChange(event.target.value)} onKeyDown={(event) => { if (!external && (event.key === "Enter" || event.key === "Tab")) { event.preventDefault(); onEnter(event.currentTarget.value); } }} placeholder={external ? `Scanner activo · ${placeholder}` : placeholder} className={`${COMPACT_FORM_FIELD} w-full border-2 ${external ? "border-orange-500 bg-orange-50/40" : "border-sky-600"} pl-9`} autoComplete="off" autoFocus={external} /></label>; }
function ScanField({ inputRef, label, value, placeholder, external, active, disabled = false, onFocus, onChange, onEnter }: { inputRef?: Ref<HTMLInputElement>; label: string; value: string; placeholder: string; external: boolean; active: boolean; disabled?: boolean; onFocus(): void; onChange(value: string): void; onEnter?(): void }) { return <label className="text-xs font-semibold">{label}<span className="relative mt-1 block"><ScanBarcode className={`pointer-events-none absolute left-3 top-2.5 z-10 h-4 w-4 ${active ? "text-orange-700" : "text-slate-400"}`} /><input ref={inputRef} data-custody-scanner="true" value={value} disabled={disabled} inputMode="text" enterKeyHint="done" onFocus={onFocus} onChange={(event) => onChange(event.target.value.trim())} onKeyDown={(event) => { if (!external && (event.key === "Enter" || event.key === "Tab") && onEnter) { event.preventDefault(); onEnter(); } }} placeholder={active && external ? `Scanner activo · ${placeholder}` : placeholder} className={`${COMPACT_FORM_FIELD} w-full border-2 pl-9 transition-colors ${active ? "border-orange-500 bg-orange-50" : "border-slate-300 bg-white"}`} /></span></label>; }
function PrepareLabel({ labelQuantity, declaredContentQuantity, saving, onLabelQuantity, onDeclaredContentQuantity, onCancel, onSave }: { labelQuantity: number; declaredContentQuantity: string; saving: boolean; onLabelQuantity(value: number): void; onDeclaredContentQuantity(value: string): void; onCancel(): void; onSave(): void }) { return <div className="mt-3 rounded border border-sky-200 bg-sky-50 p-3"><div className="grid gap-2 sm:grid-cols-2"><label className="text-xs font-semibold">Cantidad de etiquetas<input type="number" min={1} max={250} value={labelQuantity} onChange={(event) => onLabelQuantity(Math.min(250, Math.max(1, Number(event.target.value) || 1)))} className={`${COMPACT_FORM_FIELD} mt-1 w-full`} /></label><label className="text-xs font-semibold">Cantidad declarada <span className="font-normal text-slate-500">(opcional)</span><input type="number" min={1} max={9999} value={declaredContentQuantity} onChange={(event) => onDeclaredContentQuantity(event.target.value)} placeholder="Ej. 12 unidades" className={`${COMPACT_FORM_FIELD} mt-1 w-full`} /></label></div><div className="mt-2 flex flex-wrap items-center justify-between gap-2"><p className="max-w-lg text-[10px] text-slate-600">Se preparan {labelQuantity} QR únicos sin clasificar. El tipo físico se registra al describir cada unidad después de escanearla.</p><div className="flex gap-1"><button type="button" className={SECONDARY} onClick={onCancel}>Cancelar</button><button type="button" className={PRIMARY} disabled={saving || labelQuantity < 1 || labelQuantity > 250 || (!!declaredContentQuantity && (Number(declaredContentQuantity) < 1 || Number(declaredContentQuantity) > 9999))} onClick={onSave}><Printer className="h-4 w-4" />Preparar {labelQuantity} {labelQuantity === 1 ? "etiqueta" : "etiquetas"}</button></div></div></div>; }
function ConditionPanel({ item, locations, conditions, location, condition, photos, note, saving, onLocation, onCondition, onPhotos, onRemovePhoto, onNote, onSave, onFinish }: { item: CustomerStoredItem; locations: readonly CustomerCustodyCatalogItem[]; conditions: readonly CustomerCustodyCatalogItem[]; location: string | null; condition: string | null; photos: readonly string[]; note: string; saving: boolean; onLocation(value: string): void; onCondition(value: string): void; onPhotos(files: FileList | null): void; onRemovePhoto(index: number): void; onNote(value: string): void; onSave(): void; onFinish(): void }) {
  const observations = item.evidence?.map(parseObservation).filter((entry): entry is NonNullable<ReturnType<typeof parseObservation>> => entry !== null) ?? [];
  const damageSelected = Boolean(location && condition && condition !== "NO_VISIBLE_DAMAGE");
  return <div className="mt-3 rounded border border-amber-200 bg-amber-50 p-3"><div className="flex flex-wrap items-baseline justify-between gap-1"><p className="text-xs font-bold text-amber-950">{itemLabel(item)} · condición observada</p><code className="text-[8px] text-amber-800">{item.itemCode}</code></div><p className="mt-0.5 text-[10px] text-amber-800">Registre solamente lo que observa. No determine gravedad, causa ni responsabilidad.</p><p className="mt-2 text-[9px] font-black uppercase tracking-wide text-amber-900">Parte del artículo</p><div className="mt-1 flex flex-wrap gap-1">{locations.map((row) => <button key={row.catalogRef} type="button" disabled={saving} aria-pressed={location === row.code} onClick={() => onLocation(row.code)} className={`rounded border px-2 py-1 text-[10px] font-semibold ${location === row.code ? "border-amber-700 bg-amber-700 text-white" : "border-amber-300 bg-white"}`}>{row.label}</button>)}</div><p className="mt-2 text-[9px] font-black uppercase tracking-wide text-amber-900">Condición visible</p><div className="mt-1 flex flex-wrap gap-1">{conditions.map((row) => <button key={row.catalogRef} type="button" disabled={saving} aria-pressed={condition === row.code} onClick={() => onCondition(row.code)} className={`rounded border px-2 py-1 text-[10px] font-semibold ${condition === row.code ? "border-red-700 bg-red-700 text-white" : row.code === "NO_VISIBLE_DAMAGE" ? "border-emerald-300 bg-emerald-50 text-emerald-800" : "border-red-200 bg-white text-red-800"}`}>{row.label}</button>)}</div>{damageSelected && <div className="mt-3 rounded border border-red-200 bg-white p-2"><div className="flex items-center justify-between gap-2"><div><p className="text-[10px] font-black uppercase tracking-wide text-red-800">Evidencia fotográfica</p><p className="text-[10px] text-slate-500">Mínimo una fotografía. Puede registrar hasta cuatro.</p></div><label className={`${PRIMARY} h-9 w-9 shrink-0 cursor-pointer px-0`} title="Tomar fotografía del daño"><Camera className="h-4 w-4" /><span className="sr-only">Tomar fotografía del daño</span><input type="file" accept="image/*" capture="environment" multiple className="sr-only" disabled={saving || photos.length >= 4} onChange={(event) => { onPhotos(event.target.files); event.currentTarget.value = ""; }} /></label></div>{photos.length > 0 && <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">{photos.map((photo, index) => <figure key={`${photo.slice(-24)}-${index}`} className="relative overflow-hidden rounded border bg-slate-50"><img src={photo} alt={`Evidencia ${index + 1}`} className="aspect-square w-full object-cover" /><button type="button" aria-label={`Eliminar fotografía ${index + 1}`} onClick={() => onRemovePhoto(index)} className="absolute right-1 top-1 grid h-6 w-6 place-items-center rounded-full bg-white/95 text-red-700 shadow"><X className="h-3.5 w-3.5" /></button></figure>)}</div>}<label className="mt-2 block text-[10px] font-bold text-slate-700">Nota opcional<input value={note} onChange={(event) => onNote(event.target.value)} maxLength={500} placeholder="Detalle objetivo de lo observado" className={`${COMPACT_FORM_FIELD} mt-1 w-full`} /></label><div className="mt-2 flex justify-end"><button type="button" className={PRIMARY} disabled={saving || photos.length === 0} onClick={onSave}>{saving ? "Guardando…" : "Registrar evidencia"}</button></div></div>}{observations.length > 0 && <div className="mt-2 border-t border-amber-200 pt-2"><p className="text-[9px] font-black uppercase tracking-wide text-amber-900">Condiciones registradas</p><ul className="mt-1 flex flex-wrap gap-1">{observations.map((entry, index) => { const photoCount = entry.observationRef ? item.evidence?.map(parseDamagePhoto).filter((photo) => photo?.observationRef === entry.observationRef).length ?? 0 : 0; return <li key={`${entry.locationCode}-${entry.conditionCode}-${index}`} className="rounded bg-white px-2 py-1 text-[10px] text-slate-700">{locations.find((row) => row.code === entry.locationCode)?.label ?? entry.locationLabel} · {conditions.find((row) => row.code === entry.conditionCode)?.label ?? entry.conditionLabel}{photoCount > 0 ? ` · ${photoCount} foto${photoCount === 1 ? "" : "s"}` : ""}</li>; })}</ul></div>}<div className="mt-3 flex justify-end"><button type="button" className={SECONDARY} disabled={saving || damageSelected} onClick={onFinish}>Terminar inspección</button></div></div>;
}

function DamageEvidenceReport({ lot, onClose }: { lot: CustomerStorageLot; onClose(): void }) {
  const records = lot.items.flatMap((item) => {
    const evidence = item.evidence ?? [];
    const photos = evidence.map(parseDamagePhoto).filter((entry): entry is NonNullable<ReturnType<typeof parseDamagePhoto>> => entry !== null);
    const notes = evidence.map(parseDamageNote).filter((entry): entry is NonNullable<ReturnType<typeof parseDamageNote>> => entry !== null);
    return evidence.map(parseObservation).filter((entry): entry is NonNullable<ReturnType<typeof parseObservation>> => entry !== null && entry.conditionCode !== "NO_VISIBLE_DAMAGE").map((observation, index) => {
      const movement = lot.movements.find((row) => row.itemRef === item.itemRef && observation.observationRef && row.notes?.startsWith(`EVIDENCE:${observation.observationRef}|`)) ?? null;
      return { item, observation, photos: photos.filter((photo) => photo.observationRef === observation.observationRef), note: notes.find((entry) => entry.observationRef === observation.observationRef)?.note ?? null, movement, index };
    });
  });
  return <div role="dialog" aria-modal="true" aria-label="Reporte de condiciones observadas" className="fixed inset-0 z-50 overflow-auto bg-slate-950/70 p-3"><style>{`@media print { body * { visibility: hidden !important; } .damage-report-print, .damage-report-print * { visibility: visible !important; } .damage-report-print { position: absolute !important; inset: 0 !important; width: 100% !important; border: 0 !important; box-shadow: none !important; } .damage-report-actions { display: none !important; } .damage-record { break-inside: avoid; } }`}</style><div className="damage-report-print mx-auto max-w-5xl rounded-xl bg-white p-4 shadow-2xl"><header className="border-b pb-3"><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#003b70]">OSi Plus · Custodia de clientes</p><h3 className="text-lg font-black text-[#003366]">Condiciones observadas durante la recepción</h3><div className="mt-1 grid gap-1 text-xs text-slate-600 sm:grid-cols-2"><p><b>Cliente:</b> {lot.client.name}</p><p><b>Recepción:</b> {lot.manifestCode || lot.lotCode}</p><p><b>Almacén:</b> {lot.warehouse.name}</p><p><b>Zona:</b> {lot.receptionLocation.path}</p></div><p className="mt-2 text-[10px] text-slate-500">Este documento registra condiciones visibles; no determina gravedad, causa ni responsabilidad.</p></header><div className="mt-4 space-y-4">{records.map(({ item, observation, photos, note, movement, index }) => <article key={`${item.itemRef}-${observation.observationRef || index}`} className="damage-record rounded-lg border p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-black text-[#003366]">{itemLabel(item)} · {item.packageFormLabel || item.unitType}</p><p className="text-xs text-slate-600">{observation.locationLabel}: <b>{observation.conditionLabel}</b></p></div><code className="text-[9px] text-slate-500">{item.itemCode}</code></div><dl className="mt-2 grid gap-x-4 gap-y-1 text-[11px] sm:grid-cols-2"><div><dt className="font-bold text-slate-500">Fecha y hora</dt><dd>{formatDateTime(movement?.occurredAt ?? item.receivedAt)}</dd></div><div><dt className="font-bold text-slate-500">Reportado por</dt><dd>{movement?.actor.name || "Personal de almacén"}</dd></div><div><dt className="font-bold text-slate-500">Lugar</dt><dd>{lot.warehouse.name} · {movement?.origin?.path || lot.receptionLocation.path}</dd></div>{note && <div><dt className="font-bold text-slate-500">Nota</dt><dd>{note}</dd></div>}</dl>{photos.length > 0 ? <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">{photos.map((photo, photoIndex) => <figure key={`${photo.observationRef}-${photoIndex}`} className="overflow-hidden rounded border"><img src={photo.dataUrl} alt={`ART. ${inventoryNumber(item)} evidencia ${photoIndex + 1}`} className="aspect-[4/3] w-full object-cover" /><figcaption className="px-2 py-1 text-[9px] text-slate-500">Imagen {photoIndex + 1} · ART. {inventoryNumber(item)}</figcaption></figure>)}</div> : <p className="mt-3 rounded bg-amber-50 px-2 py-1 text-[10px] text-amber-800">Registro anterior sin fotografía vinculada.</p>}</article>)}{records.length === 0 && <p className="rounded bg-slate-50 px-3 py-5 text-center text-xs text-slate-500">No existen daños documentados en esta recepción.</p>}</div><div className="damage-report-actions mt-4 flex justify-end gap-2"><button type="button" className={SECONDARY} onClick={onClose}><X className="h-4 w-4" />Cerrar</button><button type="button" className={PRIMARY} disabled={records.length === 0} onClick={() => window.print()}><Printer className="h-4 w-4" />Imprimir reporte</button></div></div></div>;
}
function DescriptionForm({ item, packageFormCode, contents, note, packageForms, itemNames, saving, onPackageFormCode, onContents, onNote, onCancel, onSave }: { item: CustomerStoredItem; packageFormCode: string; contents: readonly string[]; note: string; packageForms: readonly CustomerCustodyCatalogItem[]; itemNames: readonly CustomerCustodyCatalogItem[]; saving: boolean; onPackageFormCode(value: string): void; onContents(value: readonly string[]): void; onNote(value: string): void; onCancel(): void; onSave(): void }) { return <div className="mt-3 rounded border border-sky-200 bg-sky-50 p-3"><div className="mb-2 flex flex-wrap items-baseline justify-between gap-1"><p className="text-xs font-bold text-[#003366]">{itemLabel(item)}</p><code className="text-[8px] text-slate-500">{item.itemCode}</code></div><CustodyDescriptionSearch packageFormCode={packageFormCode} contents={contents} packageForms={packageForms} itemNames={itemNames} onPackageFormCode={onPackageFormCode} onContents={onContents} /><label className="mt-2 block text-xs font-semibold">Nota opcional<input value={note} onChange={(event) => onNote(event.target.value)} className={`${COMPACT_FORM_FIELD} mt-1 w-full`} /></label><div className="mt-2 flex justify-end gap-1"><button type="button" className={SECONDARY} onClick={onCancel}>Cancelar</button><button type="button" className={PRIMARY} disabled={saving || !packageFormCode || contents.length === 0} onClick={onSave}>{saving ? "Guardando…" : "Guardar descripción"}</button></div></div>; }
function CloseReception({ lot, expected, toDescribe, holds, finalLocated, canClose, canOperate, saving, onClose }: { lot: CustomerStorageLot; expected: number; toDescribe: number; holds: number; finalLocated: number; canClose: boolean; canOperate: boolean; saving: boolean; onClose(): void }) {
  if (lot.receptionStage === "CLOSED") return <p className="mt-3 flex items-center gap-2 rounded-lg bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><CheckCircle2 className="h-4 w-4" />Recepción cerrada y almacenaje activo.</p>;
  if (canClose) return <div className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2"><p className="text-xs font-bold text-emerald-800"><CheckCircle2 className="mr-1 inline h-4 w-4" />Todo conciliado.</p><button type="button" className={PRIMARY} disabled={!canOperate || saving} onClick={onClose}><CheckCircle2 className="h-4 w-4" />Cerrar recepción</button></div>;
  return <details className="mt-3 rounded-lg border bg-slate-50 px-3 py-2 text-xs"><summary className="cursor-pointer font-bold text-slate-700"><ClipboardList className="mr-1 inline h-4 w-4" />Pendientes para cerrar la recepción</summary><div className="mt-2 grid grid-cols-2 gap-2 text-[11px] text-slate-600"><span>Por recibir: <b>{expected}</b></span><span>Por describir: <b>{toDescribe}</b></span><span>En revisión: <b>{holds}</b></span><span>Ubicados: <b>{finalLocated}/{lot.items.length}</b></span></div></details>;
}
function ConditionCatalog({ locations, conditions, onClose }: { locations: readonly CustomerCustodyCatalogItem[]; conditions: readonly CustomerCustodyCatalogItem[]; onClose(): void }) { return <div role="dialog" aria-modal="true" aria-label="Catálogo QR de condiciones" className="fixed inset-0 z-50 overflow-auto bg-slate-950/70 p-3"><style>{`@media print { body * { visibility: hidden !important; } .condition-catalog-print, .condition-catalog-print * { visibility: visible !important; } .condition-catalog-print { position: absolute !important; inset: 0 !important; width: 100% !important; border: 0 !important; box-shadow: none !important; } .condition-catalog-actions { display: none !important; } }`}</style><div className="mx-auto max-w-4xl rounded-xl bg-white p-4 shadow-2xl"><div className="condition-catalog-print"><div className="border-b pb-2"><p className="text-[10px] font-black uppercase tracking-[.18em] text-[#003b70]">OSi Plus · Custodia</p><h3 className="text-lg font-black">Catálogo rápido de condición</h3><p className="text-xs text-slate-500">Después de la etiqueta del artículo, localización y condición pueden escanearse en cualquier orden.</p></div><div className="mt-4 grid gap-6 sm:grid-cols-2"><CatalogGroup title="Localización" prefix="DLOC" rows={locations} /><CatalogGroup title="Condición" prefix="COND" rows={conditions} /></div></div><div className="condition-catalog-actions mt-4 flex justify-end gap-2"><button type="button" className={SECONDARY} onClick={onClose}><X className="h-4 w-4" />Cerrar</button><button type="button" className={PRIMARY} onClick={() => window.print()}><Printer className="h-4 w-4" />Imprimir catálogo</button></div></div></div>; }
function CatalogGroup({ title, prefix, rows }: { title: string; prefix: string; rows: readonly CustomerCustodyCatalogItem[] }) { return <section><h4 className="mb-2 border-b pb-1 text-sm font-black text-[#003b70]">{title}</h4><div className="grid grid-cols-3 gap-2">{rows.map((row) => <div key={row.catalogRef} className="grid place-items-center rounded border p-2 text-center"><QRCodeSVG value={`${prefix}:${row.code}`} size={72} level="M" /><b className="mt-1 text-[10px]">{row.label}</b><span className="font-mono text-[7px] text-slate-500">{prefix}:{row.code}</span></div>)}</div></section>; }
function DiscardUnusedLabelsDialog({ count, saving, onCancel, onConfirm }: { count: number; saving: boolean; onCancel(): void; onConfirm(): void }) { return <div role="dialog" aria-modal="true" aria-labelledby="discard-unused-labels-title" className="fixed inset-0 z-50 grid place-items-center bg-slate-950/70 p-3"><div className="w-full max-w-md rounded-xl bg-white p-4 shadow-2xl"><div className="flex items-start gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-amber-100 text-amber-800"><CircleOff className="h-5 w-5" /></span><div><h3 id="discard-unused-labels-title" className="font-black text-[#003366]">Finalizar descarga</h3><p className="mt-1 text-sm text-slate-700">Se registrará la hora de finalización.{count > 0 ? <> También se anularán <b>{count} {count === 1 ? "etiqueta no usada" : "etiquetas no usadas"}</b>.</> : null}</p><p className="mt-2 text-xs text-amber-800">Los artículos ya escaneados y sus observaciones no se modifican.</p></div></div><div className="mt-4 flex justify-end gap-2"><button type="button" className={SECONDARY} disabled={saving} onClick={onCancel}>Continuar descargando</button><button type="button" className={PRIMARY} disabled={saving} onClick={onConfirm}><CircleOff className="h-4 w-4" />{saving ? "Finalizando…" : "Confirmar finalización"}</button></div></div></div>; }
function Handoff({ lot, canOperate, saving, labelCount, onPrepareLabels, onPrintPrepared, onDiscardLabels, onVehiclePhoto, onAction }: { lot: CustomerStorageLot; canOperate: boolean; saving: boolean; labelCount: number; onPrepareLabels(): void; onPrintPrepared(): void; onDiscardLabels(): void; onVehiclePhoto(file: File | null): void; onAction(action: "ARRIVE" | "CONFIRM_HANDOFF"): void }) { const arrivalPending = ["PLANNED", "IN_TRANSIT"].includes(lot.receptionStage); const handoffPending = lot.receptionStage === "ARRIVED"; return <div><Header icon={Truck} title="Preparar la recepción" hint="Confirme la entrega y deje impresas las etiquetas antes de abrir el vehículo." badge={lot.sealNumber ? `Sello ${lot.sealNumber}` : "Sin sello"} /><div className="mt-3 divide-y rounded-lg border px-3 text-xs"><Fact icon={UserCheck} label="Responsable" value={lot.groupLeadName || "No registrado"} detail={lot.departedAt ? `Salida ${formatDateTime(lot.departedAt)}` : "Salida pendiente"} /><Fact icon={Truck} label="Transporte" value={`${lot.driverName || "Chofer no registrado"}${lot.vehicleCode ? ` · ${lot.vehicleCode}` : ""}`} detail={lot.arrivedAt ? `Llegada ${formatDateTime(lot.arrivedAt)}` : "En tránsito"} /><Fact icon={ShieldCheck} label="Recepción" value={lot.warehouse.name} detail={lot.handoffConfirmedAt ? "Custodia aceptada" : "Pendiente"} /></div><div className="mt-3 flex items-center justify-between gap-2 rounded-lg border bg-slate-50 px-3 py-2"><div className="min-w-0"><p className="text-xs font-bold text-[#003366]">Vehículo al llegar</p><p className="truncate text-[10px] text-slate-500">{lot.vehicleEvidence.length ? "Foto registrada en la recepción" : "Tome una foto antes de abrir o descargar"}</p></div><label className={`${SECONDARY} h-9 w-9 shrink-0 cursor-pointer px-0`} title="Tomar foto del vehículo"><Camera className="h-4 w-4" /><span className="sr-only">Tomar foto del vehículo</span><input type="file" accept="image/*" capture="environment" className="sr-only" disabled={!canOperate || saving} onChange={(event) => { onVehiclePhoto(event.target.files?.[0] ?? null); event.currentTarget.value = ""; }} /></label></div>{lot.vehicleEvidence[0] && <img src={lot.vehicleEvidence[0]} alt="Vehículo al llegar" className="mt-2 max-h-44 w-full rounded-lg border object-cover" />}<div className="mt-3 flex flex-wrap items-center justify-between gap-2"><p className="text-[11px] text-slate-500">{labelCount > 0 ? `${labelCount} etiquetas listas para imprimir y pegar.` : "Indique cuántas etiquetas necesita para la descarga."}</p><div className="flex flex-wrap gap-2">{labelCount > 0 && <button type="button" className={PRIMARY} onClick={onPrintPrepared}><Printer className="h-4 w-4" />Imprimir lote</button>}{labelCount > 0 && <button type="button" className={SECONDARY} disabled={!canOperate || saving} onClick={onDiscardLabels}><CircleOff className="h-4 w-4" />Anular sobrantes</button>}<button type="button" className={SECONDARY} disabled={!canOperate || saving} onClick={onPrepareLabels}><Plus className="h-4 w-4" />Más etiquetas</button>{arrivalPending && <button type="button" className={PRIMARY} disabled={!canOperate || saving} onClick={() => onAction("ARRIVE")}><Truck className="h-4 w-4" />Registrar llegada</button>}{handoffPending && <button type="button" className={PRIMARY} disabled={!canOperate || saving} onClick={() => onAction("CONFIRM_HANDOFF")}><ShieldCheck className="h-4 w-4" />Aceptar entrega</button>}{!arrivalPending && !handoffPending && <span className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-700"><CheckCircle2 className="h-4 w-4" />Entrega confirmada</span>}</div></div></div>; }
function Header({ icon: Icon, title, hint, badge, alert = false }: { icon: typeof Truck; title: string; hint: string; badge: string; alert?: boolean }) { return <div className="flex items-start justify-between gap-2"><div className="flex gap-2"><Icon className={`mt-0.5 h-4 w-4 ${alert ? "text-red-700" : "text-sky-700"}`} /><div><h5 className="text-sm font-bold text-[#003366]">{title}</h5><p className="text-[11px] text-slate-500">{hint}</p></div></div><span className={`rounded-full px-2 py-1 text-[10px] font-bold ${alert ? "bg-red-50 text-red-700" : "bg-sky-50 text-sky-800"}`}>{badge}</span></div>; }
function Metric({ label, value, alert = false }: { label: string; value: number; alert?: boolean }) { return <div className="px-2 py-1.5 text-center"><span className="block text-[9px] font-semibold uppercase text-slate-500">{label}</span><b className={`text-base ${alert ? "text-red-700" : "text-[#003366]"}`}>{value}</b></div>; }
function Fact({ icon: Icon, label, value, detail }: { icon: typeof Truck; label: string; value: string; detail: string }) { return <div className="grid min-h-12 grid-cols-[28px_minmax(0,1fr)] items-center gap-2 py-1.5 sm:grid-cols-[28px_minmax(120px,1fr)_minmax(120px,1fr)]"><span className="grid h-7 w-7 place-items-center rounded bg-sky-50 text-sky-700"><Icon className="h-4 w-4" /></span><span className="min-w-0"><b className="block">{label}</b><span className="block truncate">{value}</span></span><span className="col-start-2 text-[10px] text-slate-500 sm:col-auto sm:text-right sm:text-[11px]">{detail}</span></div>; }
function SimpleState({ text }: { text: string }) { return <p className="mt-3 rounded-lg bg-slate-50 px-3 py-4 text-center text-xs text-slate-500">{text}</p>; }
